script:
(function () {
  'use strict';
  // 401(k)/403(b) loan. Level monthly payment P = L x j / (1 - (1 + j)^-n), j = loan rate / 12,
  // n = 12 x term (P = L / n at 0%). Each payment goes back into the account. The account earns
  // i = (1 + return)^(1/12) - 1 a month: without the loan V grows untouched; with the loan, V - L
  // grows and each payment is added at the end of the month. Lost growth = difference at the end
  // of the term. After-tax cost of the 401(k) loan = interest paid (with after-tax pay) + lost
  // growth x (1 - tax rate) (account money is pre-tax); the other loan's cost is its interest.
  // Loan limit (IRC 72(p)(2)): new loan + loans owed <= lesser of $50,000 less (highest balance in
  // the last 12 months - balance owed now) and 50% of the vested balance (or $10,000 if larger and
  // the plan allows it).
  // CHECKS (Node, scratch tests): $20,000 at 8% for 5 years = $405.53 a month and $4,331.67
  // interest (standard amortization); when the loan rate matches the monthly return the account ends the
  // same with or without the loan, so lost growth is $0 and the cost is the interest; at a 0% loan
  // rate the payment is L / n; IRS examples: $80,000 vested -> $40,000 limit, $120,000 -> $50,000;
  // $15,000 vested with the $10,000 option -> $10,000; owing $10,000 now after a $30,000 high in the
  // last year: $50,000 - $20,000 - $10,000 = $20,000 more.
  // ---- Plan loan rules (IRC section 72(p)(2); IRS "Retirement Topics - Loans"), checked for 2026 --
  // These amounts are set in the statute and are not indexed for inflation.
  var RULES = {
    year: 2026,
    dollarCap: 50000,   // maximum total plan loans
    vestedShare: 0.5,   // or 50% of the vested balance, if less
    floor: 10000,       // optional plan feature: may borrow up to $10,000 even if above 50%
    maxTermYears: 5     // level repayment, at least quarterly, within 5 years (main-home loans excepted)
  };
  // --------------------------------------------------------------------------------------------------
  var HOME_MAX_TERM = 30;
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var cents = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }

  function payment(L, annualRate, n) {
    if (n <= 0) return 0;
    var j = annualRate / 12;
    return j === 0 ? L / n : L * j / (1 - Math.pow(1 + j, -n));
  }

  function maxLoan(vested, owed, highest, floorOn) {
    var dollar = RULES.dollarCap - Math.max(0, highest - owed);
    var share = RULES.vestedShare * vested;
    if (floorOn) share = Math.max(share, Math.min(RULES.floor, vested));
    return Math.max(0, Math.min(dollar, share) - owed);
  }

  function simulate(V, L, loanRate, ret, years) {
    var n = years * 12, P = payment(L, loanRate, n), j = loanRate / 12, i = Math.pow(1 + ret, 1 / 12) - 1;
    var withLoan = V - L, without = V, owe = L, rows = [];
    for (var k = 1; k <= n; k++) {
      owe = owe * (1 + j) - P;
      withLoan = withLoan * (1 + i) + P;
      without = without * (1 + i);
      if (k % 12 === 0) rows.push({ year: k / 12, owe: Math.max(0, owe), withLoan: withLoan, without: without });
    }
    return { P: P, interest: P * n - L, withLoan: withLoan, without: without, rows: rows };
  }

  function update() {
    var V = num('bkVested'), L = num('bkLoan'), rate = num('bkLoanRate'), term = num('bkTerm'), ret = num('bkReturn'),
        tax = num('bkTax'), other = num('bkOtherRate'), owed = num('bkOutstanding'), highest = num('bkHighest');
    var home = document.getElementById('bkHome').checked, floorOn = document.getElementById('bkFloor').checked;
    var maxTerm = home ? HOME_MAX_TERM : RULES.maxTermYears;
    document.getElementById('bkTerm').max = String(maxTerm);
    set('bkTermHint', home ? 'Main-home loans can run longer if your plan allows it; repaid in equal monthly payments.'
                           : 'Up to ' + RULES.maxTermYears + ' years, repaid in equal monthly payments.');
    var error = document.getElementById('bkError');
    var bad = [V, L, rate, term, ret, tax, other, owed, highest].some(isNaN) || V < 0 || L <= 0 || L > V ||
              rate < 0 || rate > 30 || term < 1 || term > maxTerm || term !== Math.floor(term) || ret < -20 || ret > 30 ||
              tax < 0 || tax > 60 || other < 0 || other > 40 || owed < 0 || highest < 0;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter a loan above $0 and no larger than your vested balance, a term of 1 to ' + maxTerm +
        ' whole years, rates up to 30% (40% for the other loan), a return from -20% to 30% and a tax rate up to 60%.';
      return;
    }
    var t = tax / 100, s = simulate(V, L, rate / 100, ret / 100, term);
    var limit = maxLoan(V, owed, highest, floorOn);
    var lost = s.without - s.withLoan;
    var otherP = payment(L, other / 100, term * 12), otherInterest = otherP * term * 12 - L;
    var cost401 = s.interest + lost * (1 - t);

    set('bkPayment', cents.format(s.P));
    set('bkMaxLabel', 'Most you can borrow (' + RULES.year + ')');
    set('bkMax', money.format(limit));
    set('bkLostLabel', lost >= 0 ? 'Lost investment growth' : 'Extra account growth');
    set('bkLost', money.format(Math.abs(lost)));
    set('bkInterest', money.format(s.interest));
    set('bkGross', cents.format(s.P / (1 - t)));
    set('bkEndNoLabel', 'Account after ' + term + (term === 1 ? ' year' : ' years') + ', no loan');
    set('bkEndYesLabel', 'Account after ' + term + (term === 1 ? ' year' : ' years') + ', with loan');
    set('bkEndNo', money.format(s.without));
    set('bkEndYes', money.format(s.withLoan));
    set('bkOtherPayment', cents.format(otherP));
    set('bkCost401', money.format(cost401));
    set('bkCostOther', money.format(otherInterest));
    var over = document.getElementById('bkOverMax');
    over.hidden = L <= limit + 0.005;
    if (!over.hidden) over.textContent = 'Federal rules cap this loan at ' + money.format(limit) +
      ' for your balance, so your plan would not lend the full ' + money.format(L) + '. The figures below show the amount you entered.';
    var diff = cost401 - otherInterest, verdict;
    if (Math.abs(diff) < 1) verdict = 'Both options cost about the same over ' + term + ' years.';
    else if (diff < 0) verdict = 'The 401(k) loan costs about ' + money.format(-diff) + ' less than the other loan over ' + term +
      ' years, as long as you keep your job and repay it on schedule.';
    else verdict = 'The other loan costs about ' + money.format(diff) + ' less than the 401(k) loan over ' + term +
      ' years, once the investment growth you would give up is counted.';
    set('bkVerdict', verdict);

    document.getElementById('bkSchedule').innerHTML = s.rows.map(function (row) {
      return '<tr><td>' + row.year + '</td><td>' + money.format(row.owe) + '</td><td>' + money.format(row.withLoan) +
             '</td><td>' + money.format(row.without) + '</td><td>' + money.format(row.withLoan - row.without) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('bkForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
